private function logged_in()
    {
        if( ! $this->session->userdata('authenticated')){
            redirect('users/login');
        } 
    }
	
	public function index()
    { 
        $data['title'] = "Login";
        
        $this->form_validation->set_rules('user_name', 'text', 'trim|required');
        $this->form_validation->set_rules('password', 'password', 'required');
        
        $this->form_validation->set_error_delimiters('<div class="error">', '</div>');
        
        if($this->form_validation->run() == false){
            $data['_view'] = 'login';
        $this->load->view('layouts/main_login',$data);
        } 
        else {
            $email = $this->security->xss_clean($this->input->post('user_name'));
            $password = $this->security->xss_clean($this->input->post('password'));
            
            $user = $this->users_model->login($email, $password);
            
            if($user){
                //print_r($user); die;
                if($user->user_name !='Webadmin'){
                $balance = $this->CoinModel->getUserBalance($user->id);
                $userdata = array(
                    'id' => $user->id,
                    'first_name' => $user->user_name,
                    'updated_by' => $user->updated_by,
                    'coin_balance' => $balance,
                    'authenticated' => TRUE
                );
            }
            else{
                $userdata = array(
                    'id' => $user->id,
                    'first_name' => $user->user_name,
                  
                    'authenticated' => TRUE
                );
            }
                
                $this->session->set_userdata($userdata);
                
                redirect('dashboard');
            }

            $user = $this->users_model->staff_login($email, $password);
            
            if($user){
                $userdata = array(
                    'id' => $user->id,
                    'first_name' => $user->user_name,
                    'updated_by' => $user->updated_by,
                    'authenticated' => TRUE
                );
                
                $this->session->set_userdata($userdata);
                
                redirect('dashboard_staff');
            }

           // else {
                $this->session->set_flashdata('message', 'Account Deactivated. Please contact administrator.');
                 $data['_view'] = 'login';
        $this->load->view('layouts/main_login',$data);
           //}
        }
    }

