    public function logout()
    {
        $this->session->sess_destroy();
        redirect('/');
    }
	
    function index1()
    { 
		$data['title'] = "Login";
		if($this->input->post('submit_login')=='login_submit')
		{
		$user_name=$this->input->post('user_name');
		$password=$this->input->post('password');
		$que=$this->db->query("select id from tbl_user_login where user_name='$user_name' and password=md5('$password')");
		$row = $que->num_rows();
		if(count($row)>0)
		{
		redirect('dashboard');
		}
		else
		{
		$data['error']="<h3 style='color:red'>Invalid userid or password !</h3>";
		}
		}
		
        $data['_view'] = 'login';
        $this->load->view('layouts/main_login',$data);
    }
	public function dashboard()
    {
		$data['ledger'] = $this->tbl_ledger_model->get_all_tbl_ledger_admin();
        $data['todate'] = date('Y-m-d', time());
			if ($this->session->userdata['id'] == 1) {
				$data['tbl_transactions'] = $this->Tbl_transactions_model->get_all_transactions_admin_may();
			} else {
				$data['tbl_transactions'] = $this->Tbl_transactions_model->view_transaction_filter($data);
			}
		//$data['shifts'] = $this->common_model->getallshift();
        
        $data['shifts'] = $this->Tbl_shift_model->get_all_tbl_shift($this->session->userdata['id']);
        $data['tbl_openno'] = $this->Tbl_openno_model->get_all_tbl_openno_admin_dashboard();
        if(isset($this->session->userdata['role']) && $this->session->userdata['role'] == 'Staff'){
            $data['_view'] = 'dashboardstaff';
            $this->load->view('layouts/mainold',$data);
        }
        else{
            $data['_view'] = 'dashboard';
            $this->load->view('layouts/main',$data);
        }
        
        
	}
	
	
}
